/**
 * CustomerFilterBar — shared filter strip for HomePage's popular section
 * and the full MenuPage.
 *
 * Surfaces:
 *   • Category pills (ALL + every entry in CATEGORIES) with horizontal
 *     scroll-snap on mobile.
 *   • VEG / NON-VEG / ALL diet toggle.
 *   • Search input (gold-bordered) that already lives in the customer theme.
 *   • Live result count "Showing N of M dishes".
 *
 * State is persisted in URL search params (`?cat=mains&veg=true&q=paneer`)
 * so back / forward / share-this-link all behave naturally.
 *
 * The bar sticks just under the steakhouse header (72 px tall) via
 * `position: sticky; top: 72px;` so it stays visible while users browse.
 *
 * Filtering itself is exposed through `useCustomerFilters()` — the page
 * calls it once to read state + the filtered list, then renders this bar.
 */

import { useMemo } from 'react'
import { useSearchParams } from 'react-router-dom'
import { Leaf, Drumstick, X, Utensils, RotateCcw } from 'lucide-react'
import { CATEGORIES, DISHES, type Dish } from '@/features/customer/catalog'
import { cn } from '@/lib/utils'

export type DietFilter = 'all' | 'veg' | 'nonveg'
export type SpiceFilter = 'any' | 'mild' | 'medium' | 'hot'

export interface CustomerFilters {
  cat: string | null
  diet: DietFilter
  spice: SpiceFilter
  q: string
  setCat: (id: string | null) => void
  setDiet: (d: DietFilter) => void
  setSpice: (s: SpiceFilter) => void
  setQ: (q: string) => void
  reset: () => void
  filtered: Dish[]
  total: number
}

/**
 * Hook backing the filter bar. Owns URL search params (`cat`, `veg`, `q`).
 */
export function useCustomerFilters(source: readonly Dish[] = DISHES): CustomerFilters {
  const [params, setParams] = useSearchParams()
  const cat = params.get('cat')
  const dietRaw = params.get('veg')
  const diet: DietFilter = dietRaw === 'true' ? 'veg' : dietRaw === 'false' ? 'nonveg' : 'all'
  const spiceRaw = params.get('spice')
  const spice: SpiceFilter =
    spiceRaw === 'mild' || spiceRaw === 'medium' || spiceRaw === 'hot' ? spiceRaw : 'any'
  const q = params.get('q') ?? ''

  const update = (patch: Record<string, string | null>): void => {
    const next = new URLSearchParams(params)
    for (const [k, v] of Object.entries(patch)) {
      if (v === null || v === '') next.delete(k)
      else next.set(k, v)
    }
    setParams(next, { replace: true })
  }

  const filtered = useMemo<Dish[]>(() => {
    const needle = q.trim().toLowerCase()
    return source.filter((d) => {
      if (cat && d.category !== cat) return false
      if (diet === 'veg' && !d.veg) return false
      if (diet === 'nonveg' && d.veg) return false
      if (spice !== 'any') {
        const level = (d.spiceLevel || '').toUpperCase().trim()
        if (spice === 'mild' && !(level === 'MILD' || level === 'LOW' || level === 'MILDLY_SPICY')) return false
        if (spice === 'medium' && !(level === 'MEDIUM' || level === 'MED' || level === 'MODERATE')) return false
        if (spice === 'hot' && !(level === 'HOT' || level === 'SPICY' || level === 'EXTRA_HOT' || level === 'VERY_HOT' || level === 'HIGH')) return false
      }
      if (!needle) return true
      return (
        d.name.toLowerCase().includes(needle) ||
        d.description.toLowerCase().includes(needle) ||
        d.category.toLowerCase().includes(needle)
      )
    })
  }, [source, cat, diet, spice, q])

  return {
    cat,
    diet,
    spice,
    q,
    setCat: (id) => update({ cat: id }),
    setDiet: (d) => update({ veg: d === 'veg' ? 'true' : d === 'nonveg' ? 'false' : null }),
    setSpice: (s) => update({ spice: s === 'any' ? null : s }),
    setQ: (next) => update({ q: next }),
    reset: () => update({ cat: null, veg: null, spice: null, q: null }),
    filtered,
    total: source.length,
  }
}

interface CustomerFilterBarProps {
  filters: CustomerFilters
  /**
   * Sticky offset from the top of the viewport. Defaults to the customer
   * header height (72 px). Pass 0 if you're rendering inline.
   */
  stickyTop?: number
  /** Hide the search input (HomePage hero may already render it). */
  hideSearch?: boolean
  /** Hide the result count footer. */
  hideCount?: boolean
  /** Hide category pills row when the page already shows image tiles for category selection. */
  hideCategoryPills?: boolean
  /** Optional id used by sr-only label. */
  searchPlaceholder?: string
}

const CAT_OPTIONS: { id: string | null; label: string }[] = [
  { id: null, label: 'All' },
  ...CATEGORIES.map((c) => ({ id: c.id as string, label: c.name })),
]

const DIET_OPTIONS: { id: DietFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'veg', label: 'Veg' },
  { id: 'nonveg', label: 'Non-veg' },
]

export function CustomerFilterBar({
  filters,
  stickyTop = 72,
  hideSearch = false,
  hideCount = false,
  hideCategoryPills = false,
  searchPlaceholder = 'Search dishes…',
}: CustomerFilterBarProps) {
  const { cat, diet, spice, q, setCat, setDiet, setSpice, setQ, reset, filtered, total } = filters
  const showingCount = filtered.length
  const hasActive = cat !== null || diet !== 'all' || spice !== 'any' || q.trim().length > 0

  return (
    <div
      className="customer-filter-bar relative z-20 backdrop-blur"
      style={{
        position: stickyTop > 0 ? 'sticky' : 'relative',
        top: stickyTop > 0 ? stickyTop : undefined,
      }}
    >
      <div className="max-w-7xl mx-auto px-3 sm:px-4 lg:px-6 py-3 space-y-2.5">
        {/* Row 1 — category pills (horizontal scroll on mobile). Hidden when
         * the host page renders its own image-tile category selector. */}
        {!hideCategoryPills ? (
          <div
            className="flex items-center gap-2 overflow-x-auto pb-1.5 -mx-1 px-1 scrollbar-hide"
            style={{ scrollSnapType: 'x mandatory' }}
          >
            {CAT_OPTIONS.map((opt) => {
              const isActive = cat === opt.id
              return (
                <button
                  key={opt.id ?? 'all'}
                  onClick={() => setCat(opt.id)}
                  className={cn(
                    'shrink-0 px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-[0.15em] border transition-all duration-300 cursor-pointer',
                    isActive
                      ? 'bg-[var(--c-primary)] text-white border-[var(--c-primary)] shadow-md shadow-black/15 scale-102'
                      : 'bg-neutral-900/30 border-white/10 hover:border-[var(--c-primary)]/40 text-[--c-text-soft] hover:text-white'
                  )}
                  style={{
                    scrollSnapAlign: 'start',
                  }}
                >
                  {opt.label}
                </button>
              )
            })}
          </div>
        ) : null}

        {/* Row 2 — diet toggle + search */}
        <div className="flex flex-col sm:flex-row sm:items-center gap-3">
          {/* Diet group */}
          <div
            className="diet-toggle-group inline-flex rounded-full overflow-hidden shrink-0 p-0.5 backdrop-blur-sm"
            role="group"
            aria-label="Dietary filter"
          >
            {DIET_OPTIONS.map((opt) => {
              const isActive = diet === opt.id
              const Icon = opt.id === 'veg' ? Leaf : opt.id === 'nonveg' ? Drumstick : Utensils
              return (
                <button
                  key={opt.id}
                  onClick={() => setDiet(opt.id)}
                  className={cn(
                    'diet-option-btn inline-flex items-center gap-1.5 px-4 py-1.5 text-[10px] font-bold uppercase tracking-[0.12em] transition-all rounded-full cursor-pointer',
                    isActive && 'diet-option-btn--active'
                  )}
                  aria-pressed={isActive}
                >
                  <Icon className={cn(
                    'size-3.5 transition-colors',
                    isActive ? 'text-white' : opt.id === 'veg' ? 'text-green-500' : opt.id === 'nonveg' ? 'text-red-500' : 'text-neutral-400'
                  )} />
                  {opt.label}
                </button>
              )
            })}
          </div>

          {/* P2.18 — Spice level chips. Real backend field `spiceLevel`. */}
          <div
            className="inline-flex rounded-full overflow-hidden shrink-0 p-0.5 border border-[var(--c-border)]"
            role="group"
            aria-label="Spice level filter"
          >
            {[
              { id: 'any' as const, label: 'Any', emoji: null },
              { id: 'mild' as const, label: 'Mild', emoji: '🌶' },
              { id: 'medium' as const, label: 'Medium', emoji: '🌶🌶' },
              { id: 'hot' as const, label: 'Hot', emoji: '🌶🌶🌶' },
            ].map((opt) => {
              const isActive = spice === opt.id
              return (
                <button
                  key={opt.id}
                  onClick={() => setSpice(opt.id)}
                  className={cn(
                    'inline-flex items-center gap-1 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.12em] transition-all rounded-full cursor-pointer',
                    isActive ? 'bg-[var(--c-terracotta)] text-white' : 'text-[var(--c-text-soft)] hover:text-[var(--c-terracotta)]',
                  )}
                  aria-pressed={isActive}
                >
                  {opt.emoji ? <span aria-hidden className="text-[9px]">{opt.emoji}</span> : null}
                  {opt.label}
                </button>
              )
            })}
          </div>

          {/* Search */}
          {!hideSearch ? (
            <div className="relative flex-1 flex flex-col sm:flex-row sm:items-center gap-3">
              <div className="relative flex-1">
                <input
                  className="c-input pl-3 pr-9 text-sm w-full"
                  placeholder={searchPlaceholder}
                  value={q}
                  onChange={(e) => setQ(e.target.value)}
                  aria-label="Search dishes"
                />
                {q ? (
                  <button
                    onClick={() => setQ('')}
                    className="absolute right-2 top-1/2 -translate-y-1/2 p-1 rounded hover:bg-[--c-bg-elev-2] cursor-pointer"
                    aria-label="Clear search"
                  >
                    <X className="size-3.5" />
                  </button>
                ) : null}
              </div>

              {/* Inline count display next to search bar */}
              {!hideCount ? (
                <p
                  className="filter-results-count text-[11px] shrink-0 font-semibold whitespace-nowrap"
                  aria-live="polite"
                >
                  <span className="gold-text">{showingCount}</span>/{total} dishes
                </p>
              ) : null}
            </div>
          ) : null}

          <button
            onClick={reset}
            className={cn(
              "reset-btn shrink-0 transition-all cursor-pointer p-1.5 rounded-full hover:bg-white/10",
              hasActive
                ? "text-white opacity-100 hover:text-[var(--c-primary)]"
                : "text-white/40 opacity-40 hover:opacity-100 hover:text-white"
            )}
            title="Reset filters"
            aria-label="Reset filters"
          >
            <RotateCcw className="w-4 h-4 text-white" size={16} />
          </button>
        </div>

        {/* Row 3 — result count (rendered here only if search is hidden) */}
        {!hideCount && hideSearch ? (
          <p
            className="filter-results-count text-[11px]"
            aria-live="polite"
          >
            <span className="gold-text font-semibold">{showingCount}</span>/{total} dishes
          </p>
        ) : null}
      </div>
    </div>
  )
}

export default CustomerFilterBar
